begin;
-- Helpers below are resolved by workflow execution after the migration commits.
-- Information pages, exact legacy redirects and migration provenance. No content seed.
create table private.site_content_settings(site_id uuid primary key,organization_id uuid not null,pages_enabled boolean not null default false,redirects_enabled boolean not null default false,foreign key(organization_id,site_id)references public.publication_sites(organization_id,id));
create table private.content_migration_records(id uuid primary key default gen_random_uuid(),organization_id uuid not null,site_id uuid not null,record jsonb not null,record_hash text not null,created_by uuid not null references public.profiles(id),created_at timestamptz not null default clock_timestamp(),decision text not null default 'needs_review'check(decision in('mapped','retain_reference','archive','needs_review')),reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,review_reason text,proof_document_id uuid references public.document_registry(id),unique(organization_id,id),foreign key(organization_id,site_id)references public.publication_sites(organization_id,id));
create unique index content_migration_identity on private.content_migration_records(site_id,(record->>'batch_id'),(record->>'record_id'));
create table private.content_migration_reviews(id uuid primary key default gen_random_uuid(),organization_id uuid not null,record_id uuid not null,reviewed_by uuid not null references public.profiles(id),decision text not null check(decision in('mapped','retain_reference','archive','needs_review')),reason text not null,proof_document_id uuid not null references public.document_registry(id),created_at timestamptz not null default clock_timestamp(),foreign key(organization_id,record_id)references private.content_migration_records(organization_id,id));
create table private.site_content_dossiers(id uuid primary key default gen_random_uuid(),organization_id uuid not null,site_id uuid not null,kind text not null check(kind in('page','redirect')),route_key text not null,route_hash text not null check(route_hash~'^[a-f0-9]{64}$'),created_by uuid not null references public.profiles(id),created_at timestamptz not null default clock_timestamp(),foreign key(organization_id,site_id)references public.publication_sites(organization_id,id),unique(organization_id,id),unique(site_id,kind,route_hash));
create table private.site_content_revisions(id uuid primary key default gen_random_uuid(),organization_id uuid not null,dossier_id uuid not null,revision integer not null check(revision>0),payload jsonb not null,payload_sha256 text not null,proof_document_id uuid not null references public.document_registry(id),proof_hash text not null,migration_record_id uuid,status text not null default 'draft'check(status in('draft','submitted','changes_requested','approved','withdrawn')),created_by uuid not null references public.profiles(id),created_at timestamptz not null default clock_timestamp(),reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,review_note text,foreign key(organization_id,dossier_id)references private.site_content_dossiers(organization_id,id),foreign key(organization_id,migration_record_id)references private.content_migration_records(organization_id,id),unique(dossier_id,revision),unique(organization_id,id));
create table private.site_content_entries(public_id uuid primary key default gen_random_uuid(),organization_id uuid not null,site_id uuid not null,dossier_id uuid not null,selected_revision_id uuid not null,epoch bigint not null default 1,published_at timestamptz not null,valid_until timestamptz,withdrawn_at timestamptz,foreign key(organization_id,site_id)references public.publication_sites(organization_id,id),foreign key(organization_id,dossier_id)references private.site_content_dossiers(organization_id,id),foreign key(organization_id,selected_revision_id)references private.site_content_revisions(organization_id,id),unique(dossier_id),check(valid_until is null or valid_until>published_at));
do $$declare t text;begin foreach t in array array['site_content_settings','content_migration_records','content_migration_reviews','site_content_dossiers','site_content_revisions','site_content_entries']loop execute format('alter table private.%I enable row level security',t);execute format('revoke all on private.%I from public,anon,authenticated,service_role',t);end loop;end$$;
create function private.f4_content_target(p text)returns boolean language sql immutable set search_path=''as $$select coalesce(length(p)<=600 and p~'^/([a-z0-9]+(-[a-z0-9]+)*(/[a-z0-9]+(-[a-z0-9]+)*)*)?([?]locale=(nl-BE|fr-BE|en))?$'and p!~'^/(api|auth|login|logout|media|creator-media|partner-media|page-media|_next)(/|[?]|$)',false)$$;
create function private.f4_content_legacy_path(p text)returns boolean language sql immutable set search_path=''as $$select coalesce(length(p)<=2000 and left(p,1)='/'and left(p,2)<>'//'and p!~'[\\?#[:cntrl:][:space:]]'and p!~*'%(2e|2f|5c|25)'and p!~'(^|/)[.]{1,2}(/|$)'and p!~*'%([^a-f0-9]|[a-f0-9][^a-f0-9]|$|[a-f0-9]$)',false)$$;
create function private.f4_content_legacy_query(p text)returns boolean language sql immutable set search_path=''as $$select coalesce(length(p)<=2000 and(p=''or(p~'^((max-results|updated-max|start|m)=[A-Za-z0-9%:.,_+-]*)([&](max-results|updated-max|start|m)=[A-Za-z0-9%:.,_+-]*)*$'and p!~*'%([^a-f0-9]|[a-f0-9][^a-f0-9]|$|[a-f0-9]$)')),false)$$;
create function private.f4_content_payload(k text,p jsonb)returns boolean language plpgsql immutable set search_path=''as $$declare x jsonb;v text;begin
 if p is null or jsonb_typeof(p)<>'object'or pg_column_size(p)>60000 then return false;end if;
 if k='page'then
  if not(p?&array['slug','locale','title','summary','body','navigation','links','hero'])or exists(select 1 from jsonb_object_keys(p)as keys(key_name)where key_name not in('slug','locale','title','summary','body','navigation','links','hero'))then return false;end if;
  if jsonb_typeof(p->'slug')is distinct from'string'or length(p->>'slug')not between 1 and 160 or p->>'slug'!~'^[a-z0-9]+(-[a-z0-9]+)*$'or p->>'slug'in('api','auth','login','logout','events','nieuws','creators','samenwerkingen','esports','vrijwilligers','mijn-besc','media','creator-media','partner-media','page-media','robots','favicon','_next')or coalesce(p->>'locale','')not in('nl-BE','fr-BE','en')then return false;end if;
  foreach v in array array['title','summary']loop if jsonb_typeof(p->v)is distinct from'string'or length(btrim(p->>v))not between 1 and(case v when'title'then 240 else 2000 end)then return false;end if;end loop;
  x:=p->'body';if jsonb_typeof(x)is distinct from'object'or not(x?&array['format','value'])or exists(select 1 from jsonb_object_keys(x)as keys(key_name)where key_name not in('format','value'))or x->>'format'is distinct from'plain_text'or jsonb_typeof(x->'value')is distinct from'string'or length(btrim(x->>'value'))not between 1 and 16000 or jsonb_typeof(p->'navigation')is distinct from'boolean'or jsonb_typeof(p->'links')is distinct from'array'then return false;end if;
  if jsonb_array_length(p->'links')>12 then return false;end if;for x in select value from jsonb_array_elements(p->'links')loop if jsonb_typeof(x)<>'object'or not(x?&array['label','href'])or exists(select 1 from jsonb_object_keys(x)as keys(key_name)where key_name not in('label','href'))or jsonb_typeof(x->'label')is distinct from'string'or length(btrim(x->>'label'))not between 1 and 120 or not private.f4_content_target(x->>'href')then return false;end if;end loop;
  return p->'hero'='null'::jsonb or private.f4_payload(jsonb_build_object('slug',p->>'slug','locale',p->>'locale','display_name','Page image','avatar',p->'hero'));
 elsif k='redirect'then
  if not(p?&array['old_host','old_path','old_query','mode','target_path'])or exists(select 1 from jsonb_object_keys(p)as keys(key_name)where key_name not in('old_host','old_path','old_query','mode','target_path'))then return false;end if;
  if coalesce(p->>'old_host','')not in('www.belgianstreamerscommunity.be','belgianstreamerscommunity.be','blog.belgianstreamerscommunity.be')or not private.f4_content_legacy_path(p->>'old_path')or not private.f4_content_legacy_query(p->>'old_query')then return false;end if;
  return(p->>'mode'='gone'and p->'target_path'='null'::jsonb)or(p->>'mode'='redirect'and private.f4_content_target(p->>'target_path')and p->>'target_path'<>(p->>'old_path')||case when p->>'old_query'=''then''else'?'||(p->>'old_query')end);
 end if;return false;
end$$;
create function private.f4_content_key(k text,p jsonb)returns text language sql immutable set search_path=''as $$select case k when'page'then(p->>'locale')||':'||(p->>'slug')else(p->>'old_host')||':'||(p->>'old_path')||'?'||(p->>'old_query')end$$;
create function private.f4_content_viewer(s uuid)returns boolean language sql stable security definer set search_path=''as $$select private.f4_identity()and exists(select 1 from public.publication_sites p where p.id=s and p.active and(private.f2_viewer(s)or exists(select 1 from private.platform_access a where a.site_id=s and a.user_id=auth.uid()and a.may_view and private.f4_access_valid(a.id))))$$;
create function private.f4_content_current(r private.site_content_revisions)returns boolean language sql stable security definer set search_path=''as $$select exists(select 1 from private.site_content_dossiers d where d.id=r.dossier_id and private.f4_content_payload(d.kind,r.payload)and d.route_key=private.f4_content_key(d.kind,r.payload))and r.proof_hash=private.f4_partner_evidence(r.organization_id,(select site_id from private.site_content_dossiers where id=r.dossier_id),r.proof_document_id,coalesce(r.payload->'hero','null'::jsonb))and(r.payload->'hero'is null or private.f4_avatar(r.organization_id,(select site_id from private.site_content_dossiers where id=r.dossier_id),jsonb_build_object('avatar',r.payload->'hero')))$$;
create function private.f4_content_entry(e private.site_content_entries)returns boolean language sql stable security definer set search_path=''as $$select e.withdrawn_at is null and e.published_at<=clock_timestamp()and(e.valid_until is null or e.valid_until>clock_timestamp())and exists(select 1 from private.site_content_revisions r join private.site_content_dossiers d on d.id=r.dossier_id join private.site_content_settings cfg on cfg.site_id=d.site_id join public.publication_sites s on s.id=d.site_id where r.id=e.selected_revision_id and r.status='approved'and d.id=e.dossier_id and d.site_id=e.site_id and s.active and(case d.kind when'page'then cfg.pages_enabled else cfg.redirects_enabled end)and private.f4_content_current(r))$$;
create function private.f4_content_target_exists(s uuid,p text)returns boolean language sql stable security definer set search_path=''as $$
 select private.f4_content_target(p)and(split_part(p,'?',1)in('/','/nieuws','/events','/creators','/samenwerkingen','/esports','/vrijwilligers','/mijn-besc')or
 exists(select 1 from private.site_content_entries e join private.site_content_dossiers d on d.id=e.dossier_id join private.site_content_revisions r on r.id=e.selected_revision_id where e.site_id=s and d.kind='page'and'/'||(r.payload->>'slug')=split_part(p,'?',1)and r.payload->>'locale'=case when position('?locale='in p)>0 then split_part(p,'?locale=',2)else'nl-BE'end and private.f4_content_entry(e))or
 exists(select 1 from public.publication_entries e where e.site_id=s and private.f2_valid(e)and('/'||case e.source_type when'news'then'nieuws'else'events'end||'/'||e.slug)=split_part(p,'?',1)and e.locale=case when position('?locale='in p)>0 then split_part(p,'?locale=',2)else'nl-BE'end))
$$;
create function private.f4_content_redirect_safe(s uuid,p jsonb)returns boolean language sql stable security definer set search_path=''as $$select p->>'old_path'not in('/','/nieuws','/events','/creators','/samenwerkingen','/esports','/vrijwilligers','/mijn-besc')and p->>'old_path'!~'^/(api|auth|login|logout|events|nieuws|creators|samenwerkingen|esports|vrijwilligers|mijn-besc|media|creator-media|partner-media|page-media|assets|robots[.]txt|favicon[.]ico|_next)(/|$)'and not exists(select 1 from private.site_content_entries x join private.site_content_dossiers y on y.id=x.dossier_id join private.site_content_revisions z on z.id=x.selected_revision_id where x.site_id=s and y.kind='page'and '/'||(z.payload->>'slug')=p->>'old_path'and private.f4_content_entry(x))and(p->>'mode'='gone'or(private.f4_content_target_exists(s,p->>'target_path')and not exists(select 1 from private.site_content_entries e join private.site_content_dossiers d on d.id=e.dossier_id join private.site_content_revisions r on r.id=e.selected_revision_id where e.site_id=s and d.kind='redirect'and e.withdrawn_at is null and private.f4_content_key('redirect',r.payload)<>private.f4_content_key('redirect',p)and((r.payload->>'old_path')||case when r.payload->>'old_query'=''then''else'?'||(r.payload->>'old_query')end=p->>'target_path'or r.payload->>'target_path'=(p->>'old_path')||case when p->>'old_query'=''then''else'?'||(p->>'old_query')end))))$$;
create function private.f4_content_proof_access(r private.site_content_revisions)returns boolean language sql stable security definer set search_path=''as $$select private.f1_document_visible(r.organization_id,r.proof_document_id)and(coalesce(r.payload->'hero','null'::jsonb)='null'::jsonb or exists(select 1 from public.publication_media m where m.public_media_id::text=r.payload->'hero'->>'public_media_id'and private.f1_document_visible(r.organization_id,m.document_id)))$$;
create function private.f4_content_migration_input(p jsonb)returns boolean language plpgsql immutable set search_path=''as $$declare k text;begin
 if p is null or jsonb_typeof(p)<>'object'or pg_column_size(p)>25000 or not(p?&array['batch_id','record_id','source_url','source_sha256','snapshot_date','classification','source_title','source_excerpt','proposed_destination','source_file','blockers'])or exists(select 1 from jsonb_object_keys(p)x where x not in('batch_id','record_id','source_url','source_sha256','snapshot_date','classification','source_title','source_excerpt','proposed_destination','source_file','blockers'))then return false;end if;
 foreach k in array array['batch_id','record_id','source_url','source_sha256','snapshot_date','classification','source_title','source_excerpt','source_file']loop if jsonb_typeof(p->k)is distinct from'string'then return false;end if;end loop;
 return p->>'batch_id'~'^[a-f0-9]{64}$'and p->>'source_sha256'~'^[a-f0-9]{64}$'and p->>'record_id'~'^URL-[0-9]{3}$'and length(p->>'source_url')between 1 and 4000 and p->>'snapshot_date'~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'and length(p->>'classification')between 1 and 60 and length(p->>'source_title')<=500 and length(p->>'source_excerpt')<=6000 and length(p->>'source_file')between 1 and 300 and(jsonb_typeof(p->'proposed_destination')='string'and length(p->>'proposed_destination')<=2000 or p->'proposed_destination'='null'::jsonb)and jsonb_typeof(p->'blockers')='array'and jsonb_array_length(p->'blockers')<=15 and not exists(select 1 from jsonb_array_elements(p->'blockers')x where jsonb_typeof(x)<>'string'or length(x#>>'{}')not between 1 and 300);
end$$;
create function public.f4_content_workflow(p_site_id uuid,p_operation text,p_data jsonb,p_request_id uuid)returns jsonb language plpgsql volatile security definer set search_path=''as $$
declare s public.publication_sites;d private.site_content_dossiers;r private.site_content_revisions;e private.site_content_entries;m private.content_migration_records;prior private.f4_receipts;op text:=p_operation;j jsonb:=p_data;allowed text[];ident uuid;v integer;h text;k text;start_at timestamptz;end_at timestamptz;answer jsonb;begin
 perform private.f4_read_gate();select * into s from public.publication_sites where id=p_site_id;if s.id is null or p_request_id is null or jsonb_typeof(j)is distinct from'object'or pg_column_size(j)>70000 then raise exception'content_not_available'using errcode='42501';end if;
 allowed:=case op when'site.configure'then array['pages_enabled','redirects_enabled','reason']when'migration.stage'then array['record']when'migration.resolve'then array['id','expected_reviews','decision','reason','proof_document_id']when'content.draft'then array['kind','dossier_id','expected_revision','payload','proof_document_id','migration_record_id']when'content.submit'then array['id','expected_hash']when'content.review'then array['id','expected_hash','decision','reason','rights_confirmed','facts_confirmed']when'content.release'then array['id','expected_hash','expected_epoch','reason','published_at','valid_until']when'content.withdraw'then array['dossier_id','reason']else null end;
 if allowed is null or not(j?&allowed)or exists(select 1 from jsonb_object_keys(j)x where not(x=any(allowed)))then raise exception'content_invalid_input';end if;
 if not private.f2_account(s.organization_id)or not(case when op='site.configure'then private.f1_chair(s.organization_id)when op in('content.review','migration.resolve')then private.f1_role(s.organization_id,'publication_reviewer')else private.f1_role(s.organization_id,'publication_editor')end)then raise exception'content_not_authorized'using errcode='42501';end if;
 if op in('content.submit','content.review','content.release')then select * into r from private.site_content_revisions where id=(j->>'id')::uuid and organization_id=s.organization_id for update;select * into d from private.site_content_dossiers where id=r.dossier_id and site_id=s.id;if d.id is null or not private.f4_content_proof_access(r)then raise exception'content_not_authorized'using errcode='42501';end if;
 elsif op='content.withdraw'then select * into d from private.site_content_dossiers where id=(j->>'dossier_id')::uuid and site_id=s.id for update;if d.id is null then raise exception'content_not_authorized'using errcode='42501';end if;
 elsif op='migration.resolve'then select * into m from private.content_migration_records where id=(j->>'id')::uuid and site_id=s.id for update;if m.id is null then raise exception'content_not_authorized'using errcode='42501';end if;end if;
 select * into prior from private.f4_receipts where site_id=s.id and actor=auth.uid()and request_id=p_request_id;if found then if prior.operation<>'content.'||op or prior.input<>j then raise exception'content_request_conflict'using errcode='40001';end if;return prior.result;end if;perform private.f4_limit(s.id,'content_write',30);
 if op='site.configure'then
  if jsonb_typeof(j->'pages_enabled')is distinct from'boolean'or jsonb_typeof(j->'redirects_enabled')is distinct from'boolean'or jsonb_typeof(j->'reason')is distinct from'string'or length(btrim(j->>'reason'))not between 2 and 2000 then raise exception'content_invalid_input';end if;insert into private.site_content_settings values(s.id,s.organization_id,(j->>'pages_enabled')::boolean,(j->>'redirects_enabled')::boolean)on conflict(site_id)do update set pages_enabled=excluded.pages_enabled,redirects_enabled=excluded.redirects_enabled;ident:=s.id;
 elsif op='migration.stage'then
  if not private.f4_content_migration_input(j->'record')then raise exception'content_invalid_input';end if;
  select * into m from private.content_migration_records where site_id=s.id and record->>'batch_id'=j->'record'->>'batch_id'and record->>'record_id'=j->'record'->>'record_id';
  h:=encode(sha256(convert_to((j->'record')::text,'UTF8')),'hex');if m.id is not null then if m.record_hash<>h then raise exception'content_source_conflict'using errcode='40001';end if;ident:=m.id;else if(select count(*)from private.content_migration_records where site_id=s.id)>=500 then raise exception'content_capacity';end if;insert into private.content_migration_records(organization_id,site_id,record,record_hash,created_by)values(s.organization_id,s.id,j->'record',h,auth.uid())returning id into ident;end if;
 elsif op='migration.resolve'then
  if m.created_by=auth.uid()then raise exception'content_independent_review_required'using errcode='42501';end if;
  if coalesce(j->>'decision','')not in('mapped','retain_reference','archive','needs_review')or jsonb_typeof(j->'reason')is distinct from'string'or length(btrim(j->>'reason'))not between 2 and 2000 or not private.f1_document_visible(s.organization_id,(j->>'proof_document_id')::uuid)or private.f4_partner_document(s.organization_id,(j->>'proof_document_id')::uuid)is null then raise exception'content_invalid_input';end if;
  if jsonb_typeof(j->'expected_reviews')is distinct from'number'or coalesce(j->>'expected_reviews','')!~'^(0|[1-9][0-9]*)$'or(select count(*)from private.content_migration_reviews where record_id=m.id)<>(j->>'expected_reviews')::integer then raise exception'content_review_conflict'using errcode='40001';end if;if(select count(*)from private.content_migration_reviews where record_id=m.id)>=50 then raise exception'content_history_limit';end if;insert into private.content_migration_reviews(organization_id,record_id,reviewed_by,decision,reason,proof_document_id)values(s.organization_id,m.id,auth.uid(),j->>'decision',j->>'reason',(j->>'proof_document_id')::uuid);
  update private.content_migration_records set decision=j->>'decision',review_reason=j->>'reason',proof_document_id=(j->>'proof_document_id')::uuid,reviewed_by=auth.uid(),reviewed_at=clock_timestamp()where id=m.id;ident:=m.id;
 elsif op='content.draft'then
  k:=j->>'kind';if k not in('page','redirect')or not coalesce(private.f4_content_payload(k,j->'payload'),false)or jsonb_typeof(j->'expected_revision')is distinct from'number'or coalesce(j->>'expected_revision','')!~'^(0|[1-9][0-9]*)$'then raise exception'content_invalid_input';end if;
  if j->'dossier_id'='null'::jsonb then
   if(j->>'expected_revision')::integer<>0 then raise exception'content_version_conflict'using errcode='40001';end if;
   if(select count(*)from private.site_content_dossiers where site_id=s.id)>=350 or(k='page'and(select count(*)from private.site_content_dossiers where site_id=s.id and kind='page'and left(route_key,length(j->'payload'->>'locale')+1)=(j->'payload'->>'locale')||':')>=50)then raise exception'content_capacity';end if;
   insert into private.site_content_dossiers(organization_id,site_id,kind,route_key,route_hash,created_by)values(s.organization_id,s.id,k,private.f4_content_key(k,j->'payload'),encode(sha256(convert_to(private.f4_content_key(k,j->'payload'),'UTF8')),'hex'),auth.uid())returning * into d;
  else select * into d from private.site_content_dossiers where id=(j->>'dossier_id')::uuid and site_id=s.id and kind=k for update;if d.id is null or d.route_key<>private.f4_content_key(k,j->'payload')then raise exception'content_route_conflict'using errcode='40001';end if;end if;
  select coalesce(max(revision),0)into v from private.site_content_revisions where dossier_id=d.id;if v<>(j->>'expected_revision')::integer then raise exception'content_version_conflict'using errcode='40001';end if;if(select count(*)from private.site_content_revisions where organization_id=s.organization_id)>=2000 then raise exception'content_capacity';end if;
  if j->'migration_record_id'<>'null'::jsonb and not exists(select 1 from private.content_migration_records where id=(j->>'migration_record_id')::uuid and site_id=s.id)then raise exception'content_source_required';end if;
  r.organization_id:=s.organization_id;r.dossier_id:=d.id;r.payload:=j->'payload';r.proof_document_id:=(j->>'proof_document_id')::uuid;r.proof_hash:=private.f4_partner_evidence(s.organization_id,s.id,r.proof_document_id,coalesce(r.payload->'hero','null'::jsonb));
  if not coalesce(private.f4_content_current(r),false)or not private.f4_content_proof_access(r)then raise exception'content_evidence_invalid';end if;
  insert into private.site_content_revisions(organization_id,dossier_id,revision,payload,payload_sha256,proof_document_id,proof_hash,migration_record_id,created_by)values(s.organization_id,d.id,v+1,r.payload,encode(sha256(convert_to(r.payload::text,'UTF8')),'hex'),r.proof_document_id,r.proof_hash,(j->>'migration_record_id')::uuid,auth.uid())returning id into ident;
 elsif op in('content.submit','content.review','content.release')then
  if j->>'expected_hash'is distinct from r.payload_sha256 then raise exception'content_hash_conflict'using errcode='40001';end if;ident:=r.id;
  if op='content.submit'then if r.created_by<>auth.uid()or r.status<>'draft'or not coalesce(private.f4_content_current(r),false)then raise exception'content_source_or_version_invalid';end if;update private.site_content_revisions set status='submitted'where id=r.id;
  elsif op='content.review'then
   if r.status<>'submitted'or r.created_by=auth.uid()then raise exception'content_independent_review_required'using errcode='42501';end if;
   if j->'rights_confirmed'is distinct from'true'::jsonb or j->'facts_confirmed'is distinct from'true'::jsonb or coalesce(j->>'decision','')not in('approved','changes_requested')or jsonb_typeof(j->'reason')is distinct from'string'or length(btrim(j->>'reason'))not between 2 and 2000 or(j->>'decision'='approved'and not coalesce(private.f4_content_current(r),false))then raise exception'content_evidence_invalid';end if;
   update private.site_content_revisions set status=j->>'decision',reviewed_by=auth.uid(),reviewed_at=clock_timestamp(),review_note=j->>'reason'where id=r.id;
  else
   if r.status<>'approved'or not coalesce(private.f4_content_current(r),false)or jsonb_typeof(j->'expected_epoch')is distinct from'number'or coalesce(j->>'expected_epoch','')!~'^(0|[1-9][0-9]*)$'or jsonb_typeof(j->'reason')is distinct from'string'or length(btrim(j->>'reason'))not between 2 and 2000 then raise exception'content_source_or_version_invalid';end if;
   if d.kind='redirect'and not coalesce(private.f4_content_redirect_safe(s.id,r.payload),false)then raise exception'content_target_or_chain_invalid';end if;
   if d.kind='page'and exists(select 1 from private.site_content_entries x join private.site_content_dossiers y on y.id=x.dossier_id join private.site_content_revisions z on z.id=x.selected_revision_id where x.site_id=s.id and y.kind='redirect'and x.withdrawn_at is null and z.payload->>'old_path'='/'||(r.payload->>'slug'))then raise exception'content_route_conflict'using errcode='40001';end if;
   select * into e from private.site_content_entries where dossier_id=d.id for update;if coalesce(e.epoch,0)<>(j->>'expected_epoch')::bigint then raise exception'content_release_conflict'using errcode='40001';end if;
   start_at:=coalesce((j->>'published_at')::timestamptz,clock_timestamp());end_at:=(j->>'valid_until')::timestamptz;if end_at is not null and end_at<=start_at then raise exception'content_invalid_window';end if;
   if e.public_id is null then insert into private.site_content_entries(organization_id,site_id,dossier_id,selected_revision_id,published_at,valid_until)values(s.organization_id,s.id,d.id,r.id,start_at,end_at)returning public_id into ident;else update private.site_content_entries set selected_revision_id=r.id,epoch=epoch+1,published_at=start_at,valid_until=end_at,withdrawn_at=null where public_id=e.public_id;ident:=e.public_id;end if;
  end if;
 else
  if jsonb_typeof(j->'reason')is distinct from'string'or length(btrim(j->>'reason'))not between 2 and 2000 then raise exception'content_invalid_input';end if;update private.site_content_entries set withdrawn_at=coalesce(withdrawn_at,clock_timestamp())where dossier_id=d.id;update private.site_content_revisions set status='withdrawn'where dossier_id=d.id and status in('submitted','approved');ident:=d.id;
 end if;answer:=jsonb_build_object('id',ident);perform private.f1_audit(s.organization_id,ident,'f4.content.'||op);insert into private.f4_receipts values(s.id,auth.uid(),p_request_id,'content.'||op,j,answer);return answer;
end$$;

create function private.f4_content_project(e private.site_content_entries)returns jsonb language sql stable security definer set search_path=''as $$select r.payload||jsonb_build_object('schema_version','besc-platform-publication-v1','type','page','public_id',e.public_id,'revision',r.revision,'published_at',e.published_at,'valid_until',e.valid_until)from private.site_content_revisions r where r.id=e.selected_revision_id$$;
create function public.f4_pages(p_site_id uuid,p_slug text default null,p_locale text default'nl-BE',p_limit integer default 50,p_before_time timestamptz default null,p_before_id uuid default null,p_search text default null)returns jsonb language plpgsql volatile security definer set search_path=''as $$declare result jsonb;begin
 perform private.f4_read_gate();if not private.f4_content_viewer(p_site_id)or not exists(select 1 from private.site_content_settings where site_id=p_site_id and pages_enabled)then raise exception'content_not_authorized'using errcode='42501';end if;
 if p_locale is null or p_locale not in('nl-BE','fr-BE','en')or p_limit is null or p_limit not between 1 and 50 or(p_before_time is null)<>(p_before_id is null)or(p_slug is not null and(length(p_slug)>160 or p_slug!~'^[a-z0-9]+(-[a-z0-9]+)*$'))or length(p_search)>80 then raise exception'content_invalid_input';end if;perform private.f4_limit(p_site_id,'content_read',180);
 select coalesce(jsonb_agg(private.f4_content_project(x)order by x.published_at desc,x.public_id desc),'[]')into result from(select e.* from private.site_content_entries e join private.site_content_dossiers d on d.id=e.dossier_id join private.site_content_revisions r on r.id=e.selected_revision_id where e.site_id=p_site_id and d.kind='page'and private.f4_content_entry(e)and r.payload->>'locale'=p_locale and(p_slug is null or r.payload->>'slug'=p_slug)and(p_before_time is null or(e.published_at,e.public_id)<(p_before_time,p_before_id))and(p_search is null or position(lower(p_search)in lower(r.payload->>'title'))>0)order by e.published_at desc,e.public_id desc limit p_limit)x;return result;
end$$;
create function public.f4_redirect_resolve(p_site_id uuid,p_host text,p_path text,p_query text)returns jsonb language plpgsql volatile security definer set search_path=''as $$declare e private.site_content_entries;r private.site_content_revisions;begin
 perform private.f4_read_gate();if not private.f4_content_viewer(p_site_id)or not exists(select 1 from private.site_content_settings where site_id=p_site_id and redirects_enabled)then raise exception'content_not_authorized'using errcode='42501';end if;
 if p_host is null or p_host not in('www.belgianstreamerscommunity.be','belgianstreamerscommunity.be','blog.belgianstreamerscommunity.be')or not private.f4_content_legacy_path(p_path)or not private.f4_content_legacy_query(p_query)then raise exception'content_invalid_input';end if;perform private.f4_limit(p_site_id,'content_read',180);
 select x.* into e from private.site_content_entries x join private.site_content_dossiers d on d.id=x.dossier_id where x.site_id=p_site_id and d.kind='redirect'and d.route_key=p_host||':'||p_path||'?'||p_query and private.f4_content_entry(x);if e.public_id is null then return null;end if;select * into r from private.site_content_revisions where id=e.selected_revision_id;if not coalesce(private.f4_content_redirect_safe(p_site_id,r.payload),false)then return null;end if;
 return jsonb_build_object('schema_version','besc-legacy-resolution-v1','public_id',e.public_id,'revision',r.revision,'status',case r.payload->>'mode'when'gone'then 410 else 307 end,'target_path',r.payload->'target_path');
end$$;
create function public.f4_content_navigation(p_site_id uuid,p_locale text default'nl-BE')returns jsonb language plpgsql volatile security definer set search_path=''as $$declare result jsonb;begin
 perform private.f4_read_gate();if not private.f4_content_viewer(p_site_id)or not exists(select 1 from private.site_content_settings where site_id=p_site_id and pages_enabled)then raise exception'content_not_authorized'using errcode='42501';end if;if p_locale is null or p_locale not in('nl-BE','fr-BE','en')then raise exception'content_invalid_input';end if;perform private.f4_limit(p_site_id,'content_read',180);
 select coalesce(jsonb_agg(jsonb_build_object('public_id',e.public_id,'slug',r.payload->>'slug','locale',r.payload->>'locale','title',r.payload->>'title','revision',r.revision)order by r.payload->>'title',e.public_id),'[]')into result from private.site_content_entries e join private.site_content_dossiers d on d.id=e.dossier_id join private.site_content_revisions r on r.id=e.selected_revision_id where e.site_id=p_site_id and d.kind='page'and private.f4_content_entry(e)and r.payload->>'locale'=p_locale and r.payload->'navigation'='true'::jsonb;return jsonb_build_object('schema_version','besc-page-navigation-v1','items',result);
end$$;
create function public.f4_content_admin(p_site_id uuid,p_section text default'revisions',p_after_time timestamptz default null,p_after_id uuid default null)returns jsonb language plpgsql volatile security definer set search_path=''as $$declare o uuid;ch boolean;ed boolean;rv boolean;ps jsonb;ms jsonb;begin
 perform private.f4_read_gate();select organization_id into o from public.publication_sites where id=p_site_id;ch:=private.f1_chair(o);ed:=private.f1_role(o,'publication_editor');rv:=private.f1_role(o,'publication_reviewer');if not private.f2_account(o)or not(ch or ed or rv)then raise exception'content_not_authorized'using errcode='42501';end if;if p_section not in('revisions','records')or(p_after_time is null)<>(p_after_id is null)then raise exception'content_invalid_input';end if;perform private.f4_limit(p_site_id,'content_admin',90);
 select coalesce(jsonb_agg(to_jsonb(x)||jsonb_build_object('current_source',coalesce(private.f4_content_current(x),false))order by x.created_at,x.id),'[]')into ps from(select r.* from private.site_content_revisions r join private.site_content_dossiers d on d.id=r.dossier_id where d.site_id=p_site_id and p_section='revisions'and(ed or rv and r.status<>'draft')and private.f4_content_proof_access(r)and(p_after_time is null or(r.created_at,r.id)>(p_after_time,p_after_id))order by r.created_at,r.id limit 50)x;
 select coalesce(jsonb_agg(to_jsonb(x)||jsonb_build_object('review_count',(select count(*)from private.content_migration_reviews where record_id=x.id),'reviews',(select coalesce(jsonb_agg(to_jsonb(v)order by v.created_at,v.id),'[]')from private.content_migration_reviews v where v.record_id=x.id and private.f1_document_visible(o,v.proof_document_id)))order by x.created_at,x.id),'[]')into ms from(select m.* from private.content_migration_records m where m.site_id=p_site_id and p_section='records'and(ed or rv)and(m.proof_document_id is null or private.f1_document_visible(o,m.proof_document_id))and(p_after_time is null or(m.created_at,m.id)>(p_after_time,p_after_id))order by m.created_at,m.id limit 50)x;
 return jsonb_build_object('chair',ch,'editor',ed,'reviewer',rv,'settings',(select to_jsonb(c)from private.site_content_settings c where c.site_id=p_site_id),'dossiers',(select coalesce(jsonb_agg(to_jsonb(d)||jsonb_build_object('revision',(select coalesce(max(revision),0)from private.site_content_revisions where dossier_id=d.id))),'[]')from private.site_content_dossiers d where d.site_id=p_site_id),'entries',(select coalesce(jsonb_agg(to_jsonb(e)||jsonb_build_object('available',coalesce(private.f4_content_entry(e),false))),'[]')from private.site_content_entries e where e.site_id=p_site_id),'record_index',case when ed or rv then(select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'record_id',m.record->>'record_id','batch_id',m.record->>'batch_id','title',m.record->>'source_title','decision',m.decision)),'[]')from private.content_migration_records m where m.site_id=p_site_id)else'[]'::jsonb end,'revisions',ps,'records',ms,'next_after',case when jsonb_array_length(case p_section when'records'then ms else ps end)=50 then jsonb_build_object('at',case p_section when'records'then(ms->-1)->>'created_at'else(ps->-1)->>'created_at'end,'id',case p_section when'records'then(ms->-1)->>'id'else(ps->-1)->>'id'end)else null end);
end$$;
create function private.f4_content_evidence_changed()returns trigger language plpgsql security definer set search_path=''as $$declare affected uuid[];begin
 if to_jsonb(new)=to_jsonb(old)then return new;end if;
 if tg_table_name='document_registry'then select array_agg(r.id)into affected from private.site_content_revisions r where r.proof_document_id=old.id or exists(select 1 from public.publication_media m where m.public_media_id::text=r.payload->'hero'->>'public_media_id'and m.document_id=old.id);
 else select array_agg(id)into affected from private.site_content_revisions where payload->'hero'->>'public_media_id'=old.public_media_id::text;end if;
 update private.site_content_entries set withdrawn_at=coalesce(withdrawn_at,clock_timestamp())where selected_revision_id=any(affected);update private.site_content_revisions set status='withdrawn'where id=any(affected)and status in('submitted','approved');if cardinality(affected)>0 then perform private.f1_audit(old.organization_id,coalesce(to_jsonb(old)->>'id',to_jsonb(old)->>'public_media_id')::uuid,'f4.content.evidence_changed');end if;return new;
end$$;
create trigger f4_content_proof_changed after update of url,label,restricted_finance,restricted_governance,media_rights_revoked_at on public.document_registry for each row execute function private.f4_content_evidence_changed();
create trigger f4_content_media_changed after update of storage_path,sha256,mime,bytes,document_id,revoked_at on public.publication_media for each row execute function private.f4_content_evidence_changed();
create function public.f4_page_media_locator(p_site_id uuid,p_media_id uuid,p_server_key text) returns jsonb language plpgsql volatile security definer set search_path='' as $$declare m public.publication_media;begin
 perform private.f4_read_gate();if not private.f4_content_viewer(p_site_id) or length(p_server_key) not between 32 and 256 or not exists(select 1 from public.publication_sites where id=p_site_id and key_sha256=encode(sha256(convert_to(p_server_key,'UTF8')),'hex')) then raise exception 'partner_not_authorized' using errcode='42501';end if;
 perform private.f4_limit(p_site_id,'partner_media',120);select * into m from public.publication_media where site_id=p_site_id and public_media_id=p_media_id and revoked_at is null;
 if m.public_media_id is null or not exists(select 1 from private.site_content_entries e join private.site_content_revisions r on r.id=e.selected_revision_id where e.site_id=p_site_id and private.f4_content_entry(e) and r.payload->'hero'->>'public_media_id'=p_media_id::text) then return null;end if;return jsonb_build_object('path',m.storage_path,'mime',m.mime,'sha256',m.sha256,'bytes',m.bytes);
end$$;


create function public.f4_page_review_media(p_site_id uuid,p_revision_id uuid,p_media_id uuid)returns boolean language plpgsql volatile security definer set search_path=''as $$declare o uuid;begin
 perform private.f4_read_gate();select organization_id into o from public.publication_sites where id=p_site_id;if not private.f2_account(o)or not(private.f1_role(o,'publication_editor')or private.f1_role(o,'publication_reviewer'))then raise exception'content_not_authorized'using errcode='42501';end if;perform private.f4_limit(p_site_id,'content_preview',120);
 return exists(select 1 from private.site_content_revisions r join private.site_content_dossiers d on d.id=r.dossier_id join public.publication_media m on m.site_id=d.site_id and m.public_media_id=p_media_id where r.id=p_revision_id and d.site_id=p_site_id and r.status<>'draft'and r.payload->'hero'->>'public_media_id'=p_media_id::text and private.f4_content_proof_access(r)and private.f4_avatar(r.organization_id,d.site_id,jsonb_build_object('avatar',r.payload->'hero')));
end$$;
create function public.f4_page_preview_locator(p_site_id uuid,p_revision_id uuid,p_media_id uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare m public.publication_media;begin
 if auth.role()<>'service_role'then raise exception'content_server_required'using errcode='42501';end if;
 select a.* into m from public.publication_media a join private.site_content_dossiers d on d.site_id=a.site_id join private.site_content_revisions r on r.dossier_id=d.id where r.id=p_revision_id and d.site_id=p_site_id and a.public_media_id=p_media_id and r.payload->'hero'->>'public_media_id'=p_media_id::text and r.status<>'draft'and private.f4_avatar(r.organization_id,d.site_id,jsonb_build_object('avatar',r.payload->'hero'));if m.public_media_id is null then return null;end if;return jsonb_build_object('path',m.storage_path,'mime',m.mime,'sha256',m.sha256,'bytes',m.bytes);
end$$;
do $$declare x record;begin for x in select n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)args from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private')and(p.proname like'f4_content_%'or p.proname in('f4_pages','f4_redirect_resolve','f4_page_media_locator','f4_page_review_media','f4_page_preview_locator'))loop execute format('revoke all on function %I.%I(%s)from public,anon,authenticated,service_role',x.nspname,x.proname,x.args);end loop;end$$;
grant execute on function public.f4_content_workflow(uuid,text,jsonb,uuid),public.f4_content_admin(uuid,text,timestamptz,uuid),public.f4_pages(uuid,text,text,integer,timestamptz,uuid,text),public.f4_content_navigation(uuid,text),public.f4_redirect_resolve(uuid,text,text,text),public.f4_page_media_locator(uuid,uuid,text),public.f4_page_review_media(uuid,uuid,uuid)to authenticated;
grant execute on function public.f4_page_preview_locator(uuid,uuid,uuid)to service_role;
commit;
